import{_ as a,o as n,c as i,ag as e}from"./chunks/framework.BZohXCq9.js";const k=JSON.parse('{"title":"VINS 直连灰度 DMA-BUF：为什么不再走 ROS 图像 Topic","description":"让 VINS 直接消费相机流水线的 NV12 Y 平面，同时保留 IMU 与里程计 ROS 接口","frontmatter":{"title":"VINS 直连灰度 DMA-BUF：为什么不再走 ROS 图像 Topic","description":"让 VINS 直接消费相机流水线的 NV12 Y 平面，同时保留 IMU 与里程计 ROS 接口","tags":["VINS","DMA-BUF","ROS","RK3588"],"date":"2026/07/18"},"headers":[],"relativePath":"uav/vins-direct-grayscale-dmabuf.md","filePath":"uav/vins-direct-grayscale-dmabuf.md","lastUpdated":1784519165000}'),p={name:"uav/vins-direct-grayscale-dmabuf.md"};function t(l,s,h,c,r,d){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="vins-直连灰度-dma-buf-为什么不再走-ros-图像-topic" tabindex="-1">VINS 直连灰度 DMA-BUF：为什么不再走 ROS 图像 Topic <a class="header-anchor" href="#vins-直连灰度-dma-buf-为什么不再走-ros-图像-topic" aria-label="Permalink to &quot;VINS 直连灰度 DMA-BUF：为什么不再走 ROS 图像 Topic&quot;">​</a></h1><p>VINS 的视觉前端最终需要的是灰度图。如果相机流水线已经产出 NV12，Y 平面本身就是灰度数据。继续把它转成 BGR、封装成 ROS Image、跨进程复制，再由 VINS 转回灰度，是一条成本很高的绕路。</p><h2 id="原来的数据路径" tabindex="-1">原来的数据路径 <a class="header-anchor" href="#原来的数据路径" aria-label="Permalink to &quot;原来的数据路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Camera buffer</span></span>
<span class="line"><span>  → BGR materialization</span></span>
<span class="line"><span>  → ROS Image serialization</span></span>
<span class="line"><span>  → ROS transport / copy</span></span>
<span class="line"><span>  → cv_bridge</span></span>
<span class="line"><span>  → grayscale conversion</span></span>
<span class="line"><span>  → VINS frontend</span></span></code></pre></div><p>这条路径的优点是接口通用、调试方便，但在多目、固定频率的板端系统里，CPU 和内存带宽会被格式转换与复制持续占用。</p><h2 id="目标路径" tabindex="-1">目标路径 <a class="header-anchor" href="#目标路径" aria-label="Permalink to &quot;目标路径&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Camera Pipeline</span></span>
<span class="line"><span>  → NV12 DMA-BUF atlas</span></span>
<span class="line"><span>  → 取 Y plane 的 geometry + fd</span></span>
<span class="line"><span>  → Unix SOCK_SEQPACKET + SCM_RIGHTS</span></span>
<span class="line"><span>  → VINS mmap 为 CV_8UC1</span></span>
<span class="line"><span>  → feature tracking</span></span></code></pre></div><p>图像不再通过 ROS topic 进入 VINS，但这不意味着整个 VINS 都脱离 ROS：</p><ul><li>IMU 仍然通过 ROS 输入；</li><li>odometry 与状态仍然通过 ROS 输出；</li><li>可选的调试图像 topic 可以继续保留；</li><li>只把高带宽、可零拷贝的图像主链迁出 ROS。</li></ul><h2 id="为什么使用-atlas" tabindex="-1">为什么使用 atlas <a class="header-anchor" href="#为什么使用-atlas" aria-label="Permalink to &quot;为什么使用 atlas&quot;">​</a></h2><p>多目系统可以把同侧多个方向的图像纵向放在一张 atlas 中。VINS 根据 ROI 的 Y 区间还原 camera id 和局部坐标，不必为每个方向单独物化一张新图。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>left atlas             right atlas</span></span>
<span class="line"><span>┌──────────┐           ┌──────────┐</span></span>
<span class="line"><span>│ camera 0 │           │ camera 1 │</span></span>
<span class="line"><span>├──────────┤           ├──────────┤</span></span>
<span class="line"><span>│ camera 2 │           │ camera 3 │</span></span>
<span class="line"><span>├──────────┤           ├──────────┤</span></span>
<span class="line"><span>│ camera 4 │           │ camera 5 │</span></span>
<span class="line"><span>├──────────┤           ├──────────┤</span></span>
<span class="line"><span>│ camera 6 │           │ camera 7 │</span></span>
<span class="line"><span>└──────────┘           └──────────┘</span></span></code></pre></div><p>四个方向仍共享同一个机体状态。每个相机通过标定外参从 <code>T_world_body</code> 得到自己的 pose，各方向的视觉 residual、IMU 因子和边缘化先验共同进入同一个滑窗优化，而不是四套独立 VINS 最后再拼接。</p><h2 id="跨进程-packet-至少要带什么" tabindex="-1">跨进程 packet 至少要带什么 <a class="header-anchor" href="#跨进程-packet-至少要带什么" aria-label="Permalink to &quot;跨进程 packet 至少要带什么&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> StereoGrayPacketV1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> magic;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint16_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> version;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sequence;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> left_timestamp_ns;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> right_timestamp_ns;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PlaneDesc left;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PlaneDesc right;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PlaneDesc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> width;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> height;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stride;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> size;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>接收端要验证 magic、版本、sequence、左右时间差、geometry、stride、offset 与溢出边界。对于 fd，还要在 mmap 前用 <code>fstat</code> 或等价方式确认真实容量足够覆盖 <code>offset + stride × height</code>。</p><h2 id="功能跑通不等于生命周期安全" tabindex="-1">功能跑通不等于生命周期安全 <a class="header-anchor" href="#功能跑通不等于生命周期安全" aria-label="Permalink to &quot;功能跑通不等于生命周期安全&quot;">​</a></h2><p>如果发送端在 <code>SCM_RIGHTS</code> 发送 fd 后立即归还 buffer，慢消费者可能读到已经被相机重新写入的内容。表面上 sequence 正常、频率正常，像素却可能属于下一帧，甚至出现撕裂。</p><p>因此，完整迁移必须补上 ACK/lease retention 或等价的回收协议。<strong>减少复制是性能优化，定义所有权才是生产化。</strong></p><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to &quot;验收要点&quot;">​</a></h2><ul><li>VINS 不再订阅左右 ROS 图像 topic；</li><li>IMU 输入与 odometry 输出仍保持兼容；</li><li>fd、geometry、stride 与 capacity 全部校验；</li><li>断开与重连后 sequence 连续性可解释；</li><li>慢消费者不会读到已复用 buffer；</li><li>性能收益来自板端 A/B，而不是只看代码路径。</li></ul><p>这类迁移的价值不只在于“绕开 ROS”，而是让高带宽图像数据遵循硬件原生内存路径，同时把 ROS 留在它更擅长的控制、状态和低带宽消息层。</p>`,22)])])}const g=a(p,[["render",t]]);export{k as __pageData,g as default};
